#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn registry_covers_all_current_mechanisms() {
        for kind in [
            ConfidentialMechanismKind::AdditiveNOfN,
            ConfidentialMechanismKind::PrivateSetIntersection,
            ConfidentialMechanismKind::PrivateSetIntersectionOprfDh,
            ConfidentialMechanismKind::ShamirThreshold,
            ConfidentialMechanismKind::ThresholdFrostSigning,
            ConfidentialMechanismKind::TrustedExecutionEnvironment,
            ConfidentialMechanismKind::TrustedExecutionEnvironmentAwsNitro,
            ConfidentialMechanismKind::FheSumFeasibility,
            ConfidentialMechanismKind::FheSumRuntime,
        ] {
            let descriptor = descriptor_for_mechanism(kind);
            assert_eq!(descriptor.kind(), kind);
            assert_eq!(ConfidentialMechanismDescriptor::new(kind), descriptor);
        }
        assert_eq!(confidential_mechanism_registry().len(), 9);
    }

    #[test]
    fn registry_marks_review_gated_external_runtime_boundaries() {
        assert!(!mechanism_requires_production_provider_review(
            ConfidentialMechanismKind::AdditiveNOfN
        ));
        assert!(!mechanism_requires_production_provider_review(
            ConfidentialMechanismKind::PrivateSetIntersection
        ));
        assert!(mechanism_requires_production_provider_review(
            ConfidentialMechanismKind::PrivateSetIntersectionOprfDh
        ));
        assert!(!mechanism_requires_production_provider_review(
            ConfidentialMechanismKind::ShamirThreshold
        ));
        assert!(mechanism_requires_production_provider_review(
            ConfidentialMechanismKind::ThresholdFrostSigning
        ));
        assert!(mechanism_requires_production_provider_review(
            ConfidentialMechanismKind::TrustedExecutionEnvironment
        ));
        assert!(mechanism_requires_production_provider_review(
            ConfidentialMechanismKind::TrustedExecutionEnvironmentAwsNitro
        ));
        assert!(!mechanism_requires_production_provider_review(
            ConfidentialMechanismKind::FheSumFeasibility
        ));
        assert!(mechanism_requires_production_provider_review(
            ConfidentialMechanismKind::FheSumRuntime
        ));
    }

    #[test]
    fn mechanism_labels_round_trip() {
        for descriptor in confidential_mechanism_registry() {
            let kind = descriptor.kind();
            assert_eq!(
                ConfidentialMechanismKind::from_label(kind.label()),
                Some(kind)
            );
        }
        assert_eq!(ConfidentialMechanismKind::from_label("unknown"), None);
    }
}
